{"source":"def investigate(context, acquire):
    events = context.get('events', [])
    decoder = None
    count = 0
    status = 'open'
    for event in events:
        op = event.get('op')
        if op == 'feed':
            data = bytes(event.get('bytes', []))
            if decoder is None:
                decoder = __import__('codecs').getincrementaldecoder('utf-8')()
            text = decoder.decode(data, False)
            if text is None:
                status = 'error'
            else:
                count += len(text)
        elif op == 'finish':
            if decoder is None:
                decoder = __import__('codecs').getincrementaldecoder('utf-8')()
            text = decoder.decode(b'', True)
            if text is None:
                status = 'error'
            else:
                count += len(text)
                status = 'finished'
        elif op == 'reset':
            decoder = __import__('codecs').getincrementaldecoder('utf-8')()
            count = 0
            status = 'open'
    return {'count': count, 'status': status}
","scope":"Native strict UTF-8 incremental decoder: lazily construct the decoder before the first feed/finish, count code points from successful decode calls, set error on malformed/incomplete-at-final input, finished on successful final decode, and reset count/status/decoder on reset.","change":"Removed the unsupported try/except syntax and added lazy decoder construction before feed and finish; decode failures are represented as None results that set status to error without adding characters, while successful calls add len(text) and finish sets finished."}
